package io.lark.column.biz;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Objects;

/**
 * Business computation node.
 *
 * <p>Node ids are generated by the framework. Inputs are typed
 * {@link ColumnStream} handles passed to the constructor, and outputs are
 * typed streams declared with {@link #fetch(Column)}. There are no string names
 * or positional indexes in business compute code:
 *
 * <pre>{@code
 * final class CtrNode
 *         extends BinaryNode<ColumnStream<Long>, ColumnStream<Long>, Double> {
 *
 *     public static final NodeSchema<Double> SCHEMA = NodeSchema.of(Metrics.CTR);
 *
 *     protected Tensor compute(ColumnContext ctx, Tensor clicks, Tensor impressions) {
 *         return Ratios.divide(clicks, impressions);
 *     }
 * }
 * }</pre>
 *
 * <p>Feeds and fetches are exposed as arrays because their arity is fixed once
 * the node is constructed.
 */
public abstract class ColumnNode {

    private final String id = NodeIds.next(getClass());
    private ColumnStream<?>[] feeds;
    private final List<ColumnStream<?>> fetchBuilder = new ArrayList<>();
    private ColumnStream<?>[] fetches;

    protected ColumnNode(ColumnStream<?>... feeds) {
        this.feeds = feeds == null ? new ColumnStream<?>[0] : feeds;
        for (ColumnStream<?> feed : this.feeds) {
            Objects.requireNonNull(feed, "feed stream");
        }
    }

    /** Bind input streams after construction; used by module wiring. */
    final void bindFeeds(ColumnStream<?>... streams) {
        if (feeds.length != 0) {
            throw new IllegalStateException(
                    "ColumnNode " + id + ": feeds are already bound");
        }
        ColumnStream<?>[] bound = streams == null
                ? new ColumnStream<?>[0] : streams.clone();
        for (ColumnStream<?> feed : bound) {
            Objects.requireNonNull(feed, "feed stream");
        }
        this.feeds = bound;
    }

    public final String id() {
        return id;
    }

    /** Fixed input streams, in constructor order. Prefer typed fields. */
    public final ColumnStream<?>[] feeds() {
        return feeds;
    }

    /** Declared output streams, in declaration order. */
    public final ColumnStream<?>[] fetches() {
        if (fetches == null) {
            fetches = fetchBuilder.toArray(ColumnStream<?>[]::new);
        }
        return fetches;
    }

    /** Declare a typed fetch output from a column definition. */
    protected final <T> ColumnStream<T> fetch(Column<T> column) {
        ColumnStream<T> stream = new ColumnStream<>(column, this);
        fetchBuilder.add(stream);
        fetches = null;
        return stream;
    }

    /** Declare a typed fetch output from a node schema. */
    protected final <T> ColumnStream<T> fetch(NodeSchema<T> schema) {
        return fetch(schema.output());
    }

    /** Business computation; read/write typed streams via {@link ColumnContext}. */
    public abstract void compute(ColumnContext ctx);

    /**
     * Optional degradation hook invoked when {@link #compute} fails.
     *
     * @return {@code true} if a usable degraded result was written
     */
    public boolean fallback(ColumnContext ctx, Throwable error) {
        return false;
    }

    @Override
    public String toString() {
        return id + Arrays.toString(fetches());
    }
}
